//! Wi-Fi authentication: PIN pairing, tokens, revocation, and the registry of
//! live sessions (one per device).
//!
//! PIN rules: generated on demand from the UI, 6 digits from the OS CSPRNG,
//! one-time, valid [`PIN_LIFETIME`], [`PIN_ATTEMPTS`] wrong attempts in total
//! (all connections together) then a new PIN must be generated by the user.
//! Tokens: 32 bytes from the OS CSPRNG, only their hash is stored
//! (`paired.rs`). USB connections never go through here: the cable is the proof.

use std::collections::HashMap;
use std::sync::{Mutex, MutexGuard, PoisonError};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use base64::Engine;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use padboard_protocol::{AuthStatus, ErrorCode, PairFailurePayload, PairFailureReason};
use serde::Serialize;
use subtle::ConstantTimeEq;
use tokio::sync::oneshot;

use crate::paired::{PairedDevice, PairedDevices};
use crate::storage::ConfigDir;

pub const PIN_LIFETIME: Duration = Duration::from_secs(120);
pub const PIN_ATTEMPTS: u32 = 5;
const TOKEN_BYTES: usize = 32;

/// How a connection reached the server.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum Transport {
    /// Loopback port, through `adb reverse`: trusted.
    Usb,
    /// TLS port on the local network: token or PIN required.
    Wifi,
}

/// Why the server ends an authenticated session by itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kick {
    Superseded,
    Revoked,
}

impl Kick {
    #[must_use]
    pub fn error_code(self) -> ErrorCode {
        match self {
            Self::Superseded => ErrorCode::Superseded,
            Self::Revoked => ErrorCode::Revoked,
        }
    }
}

// ─── Secrets ────────────────────────────────────────────────────────────

#[derive(Debug, thiserror::Error)]
#[error("the OS random generator failed: {0}")]
pub struct RandomError(getrandom::Error);

/// 6 uniformly distributed digits.
fn random_pin() -> Result<String, RandomError> {
    // Largest multiple of 10^6 that fits in a u32: rejecting values above it
    // removes the modulo bias.
    const LIMIT: u32 = u32::MAX / 1_000_000 * 1_000_000;
    loop {
        let mut bytes = [0u8; 4];
        getrandom::fill(&mut bytes).map_err(RandomError)?;
        let n = u32::from_le_bytes(bytes);
        if n < LIMIT {
            return Ok(format!("{:06}", n % 1_000_000));
        }
    }
}

/// 32 random bytes, base64url without padding (43 characters).
fn random_token() -> Result<String, RandomError> {
    let mut bytes = [0u8; TOKEN_BYTES];
    getrandom::fill(&mut bytes).map_err(RandomError)?;
    Ok(URL_SAFE_NO_PAD.encode(bytes))
}

// ─── PIN state machine (pure, time injected for tests) ───────────────────

#[derive(Debug, Clone, PartialEq, Eq)]
enum PinState {
    Idle,
    Active {
        pin: String,
        expires_at: Instant,
        /// Wall clock, for the UI countdown.
        expires_at_ms: u64,
        attempts_left: u32,
    },
    Expired,
    Locked,
    Paired {
        device_name: String,
    },
}

#[derive(Debug)]
struct Pin {
    state: PinState,
}

impl Pin {
    fn start(&mut self, pin: String, now: Instant, now_ms: u64) {
        self.state = PinState::Active {
            pin,
            expires_at: now + PIN_LIFETIME,
            expires_at_ms: now_ms + duration_ms(PIN_LIFETIME),
            attempts_left: PIN_ATTEMPTS,
        };
    }

    /// Checks a candidate PIN. On success the PIN is consumed.
    fn attempt(
        &mut self,
        candidate: &str,
        device_name: &str,
        now: Instant,
    ) -> Result<(), PairFailurePayload> {
        let fail = |reason, attempts_left| PairFailurePayload {
            reason,
            attempts_left,
        };
        let PinState::Active {
            pin,
            expires_at,
            attempts_left,
            ..
        } = &mut self.state
        else {
            return Err(match self.state {
                PinState::Locked => fail(PairFailureReason::Locked, 0),
                PinState::Expired => fail(PairFailureReason::Expired, 0),
                PinState::Idle | PinState::Paired { .. } | PinState::Active { .. } => {
                    fail(PairFailureReason::NoActivePin, 0)
                }
            });
        };
        if now >= *expires_at {
            self.state = PinState::Expired;
            return Err(fail(PairFailureReason::Expired, 0));
        }
        // Constant time; a candidate of another length simply does not match.
        if bool::from(candidate.as_bytes().ct_eq(pin.as_bytes())) {
            self.state = PinState::Paired {
                device_name: device_name.to_owned(),
            };
            return Ok(());
        }
        *attempts_left -= 1;
        if *attempts_left == 0 {
            self.state = PinState::Locked;
            return Err(fail(PairFailureReason::Locked, 0));
        }
        Err(fail(PairFailureReason::InvalidPin, *attempts_left))
    }
}

// ─── Views sent to the UI ───────────────────────────────────────────────

/// Pairing dialog state, mirrored in `src/types/status.ts`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(tag = "state", rename_all = "camelCase")]
pub enum PairingView {
    Idle,
    #[serde(rename_all = "camelCase")]
    Active {
        pin: String,
        expires_at_ms: u64,
        attempts_left: u32,
    },
    Expired,
    Locked,
    #[serde(rename_all = "camelCase")]
    Paired {
        device_name: String,
    },
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PairedDeviceView {
    pub device_id: String,
    pub name: String,
    pub paired_at_ms: u64,
    pub last_seen_ms: Option<u64>,
}

impl From<&PairedDevice> for PairedDeviceView {
    fn from(d: &PairedDevice) -> Self {
        Self {
            device_id: d.device_id.clone(),
            name: d.name.clone(),
            paired_at_ms: d.paired_at.saturating_mul(1000),
            last_seen_ms: d.last_seen.map(|s| s.saturating_mul(1000)),
        }
    }
}

/// Notified on every change, to refresh the UI.
pub type AuthListener = Box<dyn Fn(AuthChange) + Send + Sync>;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AuthChange {
    Pairing(PairingView),
    PairedDevices(Vec<PairedDeviceView>),
}

// ─── Auth: shared by the server and the UI commands ──────────────────────

struct Session {
    connection_id: u64,
    transport: Transport,
    kick: oneshot::Sender<Kick>,
}

struct Inner {
    paired: PairedDevices,
    pin: Pin,
    sessions: HashMap<String, Session>,
}

pub struct Auth {
    config: Option<ConfigDir>,
    inner: Mutex<Inner>,
    listener: AuthListener,
}

impl std::fmt::Debug for Auth {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Auth").finish_non_exhaustive()
    }
}

impl Auth {
    /// `config`: where paired devices are persisted (`None` in tests).
    #[must_use]
    pub fn new(config: Option<ConfigDir>, listener: AuthListener) -> Self {
        let paired = config
            .as_ref()
            .map(|c| c.load_or_init(PairedDevices::default))
            .unwrap_or_default();
        Self {
            config,
            inner: Mutex::new(Inner {
                paired,
                pin: Pin {
                    state: PinState::Idle,
                },
                sessions: HashMap::new(),
            }),
            listener,
        }
    }

    fn lock(&self) -> MutexGuard<'_, Inner> {
        self.inner.lock().unwrap_or_else(PoisonError::into_inner)
    }

    /// Auth status of a Wi-Fi `hello`.
    pub fn authenticate(
        &self,
        device_id: &str,
        device_name: &str,
        token: Option<&str>,
    ) -> AuthStatus {
        let Some(token) = token else {
            return AuthStatus::PairingRequired;
        };
        let mut inner = self.lock();
        if !inner.paired.verify(device_id, token) {
            return AuthStatus::TokenRejected;
        }
        inner.paired.touch(device_id, device_name, unix_now());
        self.save(&inner.paired);
        let devices = views(&inner.paired);
        drop(inner);
        (self.listener)(AuthChange::PairedDevices(devices));
        AuthStatus::Authenticated
    }

    /// Checks a PIN; on success pairs the device and returns its new token.
    ///
    /// # Errors
    /// The `pair:failure` payload to send back.
    pub fn pair(
        &self,
        device_id: &str,
        device_name: &str,
        pin: &str,
    ) -> Result<String, PairFailurePayload> {
        let mut inner = self.lock();
        let result = inner.pin.attempt(pin, device_name, Instant::now());
        let outcome = match result {
            Ok(()) => match random_token() {
                Ok(token) => {
                    inner
                        .paired
                        .insert(device_id, device_name, &token, unix_now());
                    self.save(&inner.paired);
                    tracing::info!(device = device_name, "device paired");
                    Ok(token)
                }
                Err(e) => {
                    tracing::error!("{e}");
                    inner.pin.state = PinState::Idle;
                    Err(PairFailurePayload {
                        reason: PairFailureReason::NoActivePin,
                        attempts_left: 0,
                    })
                }
            },
            Err(failure) => {
                tracing::warn!(device = device_name, ?failure, "pairing attempt refused");
                Err(failure)
            }
        };
        let pairing = pin_view(&inner.pin);
        let devices = views(&inner.paired);
        drop(inner);
        (self.listener)(AuthChange::Pairing(pairing));
        if outcome.is_ok() {
            (self.listener)(AuthChange::PairedDevices(devices));
        }
        outcome
    }

    /// Shows a new PIN (replacing any previous one).
    ///
    /// # Errors
    /// If the OS random generator fails.
    pub fn start_pairing(&self) -> Result<PairingView, RandomError> {
        let pin = random_pin()?;
        let mut inner = self.lock();
        inner.pin.start(pin, Instant::now(), now_ms());
        let view = pin_view(&inner.pin);
        drop(inner);
        (self.listener)(AuthChange::Pairing(view.clone()));
        Ok(view)
    }

    pub fn cancel_pairing(&self) {
        self.lock().pin.state = PinState::Idle;
        (self.listener)(AuthChange::Pairing(PairingView::Idle));
    }

    /// Forgets a device and closes its live Wi-Fi session. Returns `false`
    /// if it was not paired. A USB session stays: USB needs no pairing.
    pub fn revoke(&self, device_id: &str) -> bool {
        let mut inner = self.lock();
        if !inner.paired.remove(device_id) {
            return false;
        }
        self.save(&inner.paired);
        if inner
            .sessions
            .get(device_id)
            .is_some_and(|s| s.transport == Transport::Wifi)
            && let Some(session) = inner.sessions.remove(device_id)
        {
            let _ = session.kick.send(Kick::Revoked);
        }
        let devices = views(&inner.paired);
        drop(inner);
        tracing::info!(device_id, "pairing revoked");
        (self.listener)(AuthChange::PairedDevices(devices));
        true
    }

    /// Registers the authenticated session of a device; a previous session of
    /// the same device is told to close (`superseded`). The receiver fires if
    /// this session must close in turn.
    pub fn open_session(
        &self,
        device_id: &str,
        connection_id: u64,
        transport: Transport,
    ) -> oneshot::Receiver<Kick> {
        let (tx, rx) = oneshot::channel();
        let previous = self.lock().sessions.insert(
            device_id.to_owned(),
            Session {
                connection_id,
                transport,
                kick: tx,
            },
        );
        if let Some(previous) = previous {
            tracing::info!(
                device_id,
                old = previous.connection_id,
                new = connection_id,
                "session superseded"
            );
            let _ = previous.kick.send(Kick::Superseded);
        }
        rx
    }

    pub fn close_session(&self, device_id: &str, connection_id: u64) {
        let mut inner = self.lock();
        if inner
            .sessions
            .get(device_id)
            .is_some_and(|s| s.connection_id == connection_id)
        {
            inner.sessions.remove(device_id);
        }
    }

    #[cfg(test)]
    #[must_use]
    pub fn pairing(&self) -> PairingView {
        pin_view(&self.lock().pin)
    }

    #[must_use]
    pub fn paired_devices(&self) -> Vec<PairedDeviceView> {
        views(&self.lock().paired)
    }

    fn save(&self, paired: &PairedDevices) {
        if let Some(config) = &self.config
            && let Err(e) = config.save(paired)
        {
            tracing::error!("cannot save the paired devices: {e}");
        }
    }
}

fn pin_view(pin: &Pin) -> PairingView {
    match &pin.state {
        PinState::Idle => PairingView::Idle,
        PinState::Active {
            pin,
            expires_at_ms,
            attempts_left,
            ..
        } => PairingView::Active {
            pin: pin.clone(),
            expires_at_ms: *expires_at_ms,
            attempts_left: *attempts_left,
        },
        PinState::Expired => PairingView::Expired,
        PinState::Locked => PairingView::Locked,
        PinState::Paired { device_name } => PairingView::Paired {
            device_name: device_name.clone(),
        },
    }
}

fn views(paired: &PairedDevices) -> Vec<PairedDeviceView> {
    paired.devices.iter().map(PairedDeviceView::from).collect()
}

fn duration_ms(d: Duration) -> u64 {
    u64::try_from(d.as_millis()).unwrap_or(u64::MAX)
}

fn now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(duration_ms)
        .unwrap_or_default()
}

fn unix_now() -> u64 {
    now_ms() / 1000
}

#[cfg(test)]
mod tests {
    use std::sync::Arc;

    use super::*;

    fn pin_with(code: &str, now: Instant) -> Pin {
        let mut pin = Pin {
            state: PinState::Idle,
        };
        pin.start(code.into(), now, 0);
        pin
    }

    fn reason(r: Result<(), PairFailurePayload>) -> (PairFailureReason, u32) {
        let e = r.unwrap_err();
        (e.reason, e.attempts_left)
    }

    #[test]
    fn pins_are_six_digits() {
        for _ in 0..200 {
            let pin = random_pin().unwrap();
            assert_eq!(pin.len(), 6);
            assert!(pin.bytes().all(|b| b.is_ascii_digit()), "{pin}");
        }
    }

    #[test]
    fn tokens_are_32_random_bytes() {
        let a = random_token().unwrap();
        assert_eq!(URL_SAFE_NO_PAD.decode(&a).unwrap().len(), TOKEN_BYTES);
        assert_ne!(a, random_token().unwrap());
    }

    #[test]
    fn right_pin_pairs_once() {
        let t0 = Instant::now();
        let mut pin = pin_with("123456", t0);
        assert_eq!(pin.attempt("123456", "Tab", t0), Ok(()));
        assert_eq!(
            pin.state,
            PinState::Paired {
                device_name: "Tab".into()
            }
        );
        // One-time: the same PIN no longer works.
        assert_eq!(
            reason(pin.attempt("123456", "Tab", t0)),
            (PairFailureReason::NoActivePin, 0)
        );
    }

    #[test]
    fn five_wrong_attempts_lock_the_pin() {
        let t0 = Instant::now();
        let mut pin = pin_with("123456", t0);
        for left in (1..PIN_ATTEMPTS).rev() {
            assert_eq!(
                reason(pin.attempt("000000", "Tab", t0)),
                (PairFailureReason::InvalidPin, left)
            );
        }
        assert_eq!(
            reason(pin.attempt("999999", "Tab", t0)),
            (PairFailureReason::Locked, 0)
        );
        // Even the right PIN is refused now: a new one is required.
        assert_eq!(
            reason(pin.attempt("123456", "Tab", t0)),
            (PairFailureReason::Locked, 0)
        );
        pin.start("654321".into(), t0, 0);
        assert_eq!(pin.attempt("654321", "Tab", t0), Ok(()));
    }

    #[test]
    fn pin_expires_after_two_minutes() {
        let t0 = Instant::now();
        let mut pin = pin_with("123456", t0);
        let almost = t0 + PIN_LIFETIME - Duration::from_millis(1);
        assert_eq!(
            reason(pin.attempt("000000", "Tab", almost)),
            (PairFailureReason::InvalidPin, PIN_ATTEMPTS - 1)
        );
        assert_eq!(
            reason(pin.attempt("123456", "Tab", t0 + PIN_LIFETIME)),
            (PairFailureReason::Expired, 0)
        );
        // Stays expired until the user generates a new PIN.
        assert_eq!(
            reason(pin.attempt("123456", "Tab", t0)),
            (PairFailureReason::Expired, 0)
        );
    }

    #[test]
    fn malformed_pins_count_as_wrong() {
        let t0 = Instant::now();
        let mut pin = pin_with("123456", t0);
        // 4 malformed attempts: the 5th wrong attempt would lock the PIN.
        for bad in ["", "12345", "1234567", "１２３４５６"] {
            assert_eq!(
                reason(pin.attempt(bad, "Tab", t0)).0,
                PairFailureReason::InvalidPin,
                "{bad:?}"
            );
        }
    }

    #[test]
    fn no_pin_means_no_pairing() {
        let mut pin = Pin {
            state: PinState::Idle,
        };
        assert_eq!(
            reason(pin.attempt("123456", "Tab", Instant::now())),
            (PairFailureReason::NoActivePin, 0)
        );
    }

    fn auth() -> (Auth, Arc<Mutex<Vec<AuthChange>>>) {
        let changes = Arc::new(Mutex::new(Vec::new()));
        let sink = Arc::clone(&changes);
        let auth = Auth::new(None, Box::new(move |c| sink.lock().unwrap().push(c)));
        (auth, changes)
    }

    fn active_pin(auth: &Auth) -> String {
        let PairingView::Active { pin, .. } = auth.start_pairing().unwrap() else {
            panic!("expected an active PIN");
        };
        pin
    }

    #[test]
    fn pairing_issues_a_token_that_authenticates() {
        let (auth, changes) = auth();
        assert_eq!(
            auth.authenticate("tab", "Tab", None),
            AuthStatus::PairingRequired
        );
        assert_eq!(
            auth.authenticate("tab", "Tab", Some("guess")),
            AuthStatus::TokenRejected
        );

        let pin = active_pin(&auth);
        let token = auth.pair("tab", "Galaxy Tab A", &pin).unwrap();
        assert_eq!(
            auth.authenticate("tab", "Galaxy Tab A", Some(&token)),
            AuthStatus::Authenticated
        );
        assert_eq!(
            auth.authenticate("other", "Other", Some(&token)),
            AuthStatus::TokenRejected
        );
        assert_eq!(auth.paired_devices()[0].name, "Galaxy Tab A");
        assert_eq!(
            auth.pairing(),
            PairingView::Paired {
                device_name: "Galaxy Tab A".into()
            }
        );
        assert!(
            changes
                .lock()
                .unwrap()
                .iter()
                .any(|c| matches!(c, AuthChange::PairedDevices(d) if d.len() == 1))
        );
    }

    #[test]
    fn revoking_rejects_the_token_and_kicks_the_wifi_session() {
        let (auth, _) = auth();
        let pin = active_pin(&auth);
        let token = auth.pair("tab", "Tab", &pin).unwrap();
        let mut kicked = auth.open_session("tab", 1, Transport::Wifi);

        assert!(auth.revoke("tab"));
        assert_eq!(kicked.try_recv(), Ok(Kick::Revoked));
        assert_eq!(
            auth.authenticate("tab", "Tab", Some(&token)),
            AuthStatus::TokenRejected
        );
        assert!(!auth.revoke("tab"));
    }

    #[test]
    fn revoking_keeps_a_usb_session() {
        let (auth, _) = auth();
        let pin = active_pin(&auth);
        auth.pair("tab", "Tab", &pin).unwrap();
        let mut usb = auth.open_session("tab", 1, Transport::Usb);
        assert!(auth.revoke("tab"));
        assert!(usb.try_recv().is_err());
    }

    #[test]
    fn a_new_session_supersedes_the_previous_one() {
        let (auth, _) = auth();
        let mut wifi = auth.open_session("tab", 1, Transport::Wifi);
        let mut usb = auth.open_session("tab", 2, Transport::Usb);
        assert_eq!(wifi.try_recv(), Ok(Kick::Superseded));
        // Closing the old session must not unregister the new one.
        auth.close_session("tab", 1);
        let _third = auth.open_session("tab", 3, Transport::Wifi);
        assert_eq!(usb.try_recv(), Ok(Kick::Superseded));
    }

    #[test]
    fn paired_devices_are_persisted() {
        let tmp = tempfile::tempdir().unwrap();
        let config = ConfigDir::open(tmp.path()).unwrap();
        let auth = Auth::new(Some(config.clone()), Box::new(|_| {}));
        let pin = active_pin(&auth);
        let token = auth.pair("tab", "Tab", &pin).unwrap();

        let reloaded = Auth::new(Some(config), Box::new(|_| {}));
        assert_eq!(
            reloaded.authenticate("tab", "Tab", Some(&token)),
            AuthStatus::Authenticated
        );
    }
}
